package com.android.messaging.ui.conversation;
import android.content.Context;import android.graphics.Color;import android.provider.Telephony;import android.text.format.DateFormat;import android.util.AttributeSet;import android.view.Gravity;import android.view.View;import android.widget.FrameLayout;import android.widget.LinearLayout;import android.widget.TextView;import com.android.messaging.R;import com.android.messaging.sms.SmsRepository;import com.android.messaging.ui.ContactIconView;import com.android.messaging.util.AppPrefs;import com.android.messaging.util.ContactResolver;import java.util.Date;
public class ConversationMessageView extends FrameLayout {private LinearLayout row,bubble;private TextView text,status;private ContactIconView icon;public ConversationMessageView(Context c,AttributeSet a){super(c,a);}@Override protected void onFinishInflate(){super.onFinishInflate();row=findViewById(R.id.message_row);bubble=findViewById(R.id.message_content);text=findViewById(R.id.message_text);status=findViewById(R.id.message_status);icon=findViewById(R.id.conversation_icon);}@Override protected void onMeasure(int widthSpec,int heightSpec){int width=View.MeasureSpec.getSize(widthSpec)-getPaddingLeft()-getPaddingRight();int reserve=com.android.messaging.util.UiUtil.dp(getContext(),56);int inner=com.android.messaging.util.UiUtil.dp(getContext(),32);int maximum=Math.max(1,width-reserve-inner);text.setMaxWidth(maximum);status.setMaxWidth(maximum);super.onMeasure(widthSpec,heightSpec);}public void bind(SmsRepository.Message m,String address){boolean in=m.type==Telephony.Sms.MESSAGE_TYPE_INBOX;row.setGravity(in?Gravity.START:Gravity.END);int color=in?AppPrefs.incoming(getContext()):AppPrefs.conversationColor(getContext(),address);bubble.setBackground(new MessageBubbleBackground(color,in,getResources().getDisplayMetrics().density));int fg=readable(color);text.setTextColor(fg);status.setTextColor(fg==Color.WHITE?0xb3ffffff:0x8a000000);text.setText(m.body==null?"":m.body);String st=DateFormat.getTimeFormat(getContext()).format(new Date(m.date));if(m.type==Telephony.Sms.MESSAGE_TYPE_FAILED)st="Failed · "+st;else if(m.type==Telephony.Sms.MESSAGE_TYPE_OUTBOX||m.type==Telephony.Sms.MESSAGE_TYPE_QUEUED)st="Sending · "+st;else if(!in&&m.status==Telephony.Sms.STATUS_COMPLETE)st="Delivered · "+st;status.setText(st);if(in){icon.setVisibility(View.VISIBLE);icon.bind(ContactResolver.name(getContext(),address),address);}else icon.setVisibility(View.GONE);}private int readable(int c){double l=(.299*Color.red(c)+.587*Color.green(c)+.114*Color.blue(c))/255d;return l>.62?Color.BLACK:Color.WHITE;}}
